        // ── AUTO PING MONITOR ─────────────────────────────────────────────────

        private SpeedTestService? _pingSvc;

        private bool _pingRunning = false;
        private bool _optimizerOpen = false;

        private void StartAutoPing(string host)
        {
            _pingCts?.Cancel(); _pingCts?.Dispose();
            _pingSvc?.Dispose();
            _pingCts = new CancellationTokenSource();
            _pingHistIdx = _pingTotalCount = _pingLostCount = 0;
            _pingConsecutiveLost = 0;
            _pingTimeoutEvents.Clear();
            for (int i = 0; i < _pingHistory.Length; i++) { _pingHistory[i] = float.NaN; _pingTimeTicks[i] = 0; }

            _pingRunning = true;
            // Stop dashboard background ping — both write to same buffer → double speed
            _dashPingCts?.Cancel();

            _pingSvc = new SMDWin.Services.SpeedTestService();
            _ = _pingSvc.ContinuousPingAsync(host, pingMs =>
            {
                _ = Dispatcher.InvokeAsync(() =>
                {
                    _pingTotalCount++;
                    if (pingMs < 0 && (DateTime.UtcNow - _lastResumeUtc).TotalSeconds < 45)
                    {
                        // after waking from sleep the network reconnects for a few seconds: not a real loss
                        _pingConsecutiveLost = 0;
                        _pingTotalCount--;
                        return;
                    }
                    if (pingMs < 0)
                    {
                        _pingLostCount++;
                        _pingConsecutiveLost++;
                        if (_pingConsecutiveLost == PingLossThreshold)
                        {
                            _pingTimeoutEvents.Add((DateTime.Now.AddSeconds(-PingLossThreshold), null, null));

                            int eventIdx = _pingTimeoutEvents.Count - 1;
                            _ = Task.Run(async () =>
                            {
                                try
                                {
                                    var diag = await SMDWin.Services.NetworkDiagnosisService.RunAsync();
                                    await Dispatcher.InvokeAsync(() =>
                                    {
                                        if (eventIdx >= 0 && eventIdx < _pingTimeoutEvents.Count)
                                        {
                                            var ev = _pingTimeoutEvents[eventIdx];
                                            bool allOkLog = diag.AdapterOk && diag.RouterOk && diag.InternetOk && diag.DnsOk && diag.HttpOk;
                                            string logDiag = allOkLog ? _LS("NetDiag", "ShortBriefBlip") : diag.ShortSummary;
                                            _pingTimeoutEvents[eventIdx] = (ev.Start, ev.End, logDiag);
                                            PingDataUpdated?.Invoke(); // refresh the Ping Monitor window if it is open
                                        }
                                        bool allOk = diag.AdapterOk && diag.RouterOk && diag.InternetOk && diag.DnsOk && diag.HttpOk;
                                        string pingMsg = allOk
                                            ? string.Format(_LS("Notif", "PingLostMsgBlip"), host)
                                            : string.Format(_LS("Notif", "PingLostMsgDiag"), host, diag.ShortSummary);
                                        SendWindowsNotif(
                                            _LS("Notif", "PingLostTitle"),
                                            pingMsg,
                                            ref _lastPingLostNotif, 60, Forms.ToolTipIcon.Warning);
                                        SMDWin.Services.NotificationCenter.Add(SMDWin.Services.NotifCategory.Network,
                                            allOk ? SMDWin.Services.NotifSeverity.Info : SMDWin.Services.NotifSeverity.Warning,
                                            pingMsg);
                                    });
                                }
                                catch (Exception ex)
                                {
                                    AppLogger.Debug($"Auto network diagnosis: {ex.Message}");
                                    // Fallback: if the diagnosis itself failed, at least tell the user with the old generic message — better than silence.
                                    await Dispatcher.InvokeAsync(() =>
                                    {
                                        string fallbackMsg = string.Format(_LS("Notif", "PingLostMsg"), host);
                                        SendWindowsNotif(
                                            _LS("Notif", "PingLostTitle"),
                                            fallbackMsg,
                                            ref _lastPingLostNotif, 60, Forms.ToolTipIcon.Warning);
                                        SMDWin.Services.NotificationCenter.Add(SMDWin.Services.NotifCategory.Network,
                                            SMDWin.Services.NotifSeverity.Warning, fallbackMsg);
                                    });
                                }
                            });
                        }
                    }
                    else
                    {
                        // Close the active episode (if any) on the first good reply.
                        if (_pingConsecutiveLost >= PingLossThreshold && _pingTimeoutEvents.Count > 0)
                        {
                            var last = _pingTimeoutEvents[^1];
                            if (last.End == null) _pingTimeoutEvents[^1] = (last.Start, DateTime.Now, last.Diagnosis);
                        }
                        _pingConsecutiveLost = 0;
                    }
                    // EMA smoothing on ping (alpha=0.3) — avoids a "jittery" chart
                    float rawPing = (float)Math.Max(0, pingMs);
                    float prevPing = _pingHistory[Math.Max(0, _pingHistIdx - 1) % _pingHistory.Length];
                    float smoothedPing = (float.IsNaN(prevPing) || prevPing <= 0)
                        ? rawPing
                        : 0.3f * rawPing + 0.7f * prevPing;
                    _pingHistory[_pingHistIdx % _pingHistory.Length] = pingMs < 0 ? float.NaN : smoothedPing;
                    _pingTimeTicks[_pingHistIdx % _pingTimeTicks.Length] = DateTime.Now.Ticks;
                    _pingHistIdx++;

                    PingDataUpdated?.Invoke();
                });
            }, _pingCts.Token);
        }

        private void InitPingBackgroundTrackingOnStartup()
        {
            try
            {
                if (!SettingsService.Current.PingBackgroundTrackingEnabled) return;
                string host = string.IsNullOrWhiteSpace(SettingsService.Current.PingBackgroundHost)
                    ? "8.8.8.8" : SettingsService.Current.PingBackgroundHost;
                StartAutoPing(host);
            }
            catch (Exception ex) { AppLogger.Warning(ex, "InitPingBackgroundTrackingOnStartup"); }
        }
    }
